\label{prop1}
For all non-negative integers $m,n$ and integers $k,l$, 
one has 
\begin{equation*}
{\cal L}(S(k,m)) * {\cal L}(S(l,n)) \geq {\cal L}(S(k+l,m+n)).
\end{equation*}

\label{prop4}
For all $k \in {\mathds Z}$ and $m,n \in {\mathds N}$
we have
\begin{align}
\mu(k,n) &\geq \mu(k+1,n), 
	\label{twelve} \\
\mu(k,n+m) &\leq \sum_l \beta(m,l) \mu(k-l,n), \ \text{and} 
	\label{thirteena} \\
\mu(k,n+m) &\geq \sum_l \beta(m,l) \mu(k+l,n), 
	\label{thirteenb}
\end{align}
where $\beta(m,\cdot)$ is the binomial distribution
with mean $\frac m 2$ and variance $\frac m 4$.

\label{prop5}
If $h$ is differentiable at $v$,
any weak limit $\mu^*$ of the measures $\mu(\lfloor un \rfloor , n)$, 
$n \rightarrow \infty$, is of the form
\begin{equation*}
\mu^* = \int_0^1 \mu_t \, \rho(dt)
\end{equation*}
with $\rho$ some probability distribution on $[0,1]$,
and with $\mu_t$ defined as in section~\ref{sec:reduction}~(there we called it $\mu_d$).

\label{prop6}
Assume $h$ is differentiable at ${\overline{u}}$.
For any finite set $F$ of cardinality $n$ and any $\epsilon > 0$
there exists a $\delta > 0$ and $n_0 \in {\mathds N}$ such that
\begin{equation}
\label{sixteen}
|\rho(\lfloor un \rfloor,F;n)-\rho(\lfloor {\overline{u}} n \rfloor,F;n)| 
\leq \epsilon
\end{equation}
for $|u - {\overline{u}} | \leq \delta$ and $n \geq n_0$, and
\begin{equation}
\label{seventeen}
|\rho(\lfloor {\overline{u}} n \rfloor,F;n+m)-
\rho(\lfloor {\overline{u}} n \rfloor,F;n)| 
\leq \epsilon
\end{equation}
for $0 \leq m \leq \delta n$ and $n \geq n_0$.

First let us prove \eqref{sixteen}.
By symmetry, it suffices to handle the case $u>{\overline{u}}$.

Since $\mu(k,n)$ is stochastically decreasing in $k$
we need an upper estimate only for
\begin{equation}
\label{nolabel}
\rho(\lfloor {\overline{u}} n \rfloor , F; n)
 - \rho(\lfloor u n \rfloor , F ; n) .
\end{equation}
But the definition of stochastic order (via coupling) 
gives us such an estimate:
\begin{equation}

\sum_{i \in F} \bigl( \rho( \lfloor {\overline{u}} \rfloor , \{i\} ; n)
                    - \rho( \lfloor u \rfloor , \{i\} ; n) \bigr)
= \sum_{i \in F} 
{\cal E}(X(\lfloor {\overline{u}} n \rfloor + i , n) - X(\lfloor u n \rfloor + i , n)).
\end{equation}
Take $\delta>0$ such that $h'({\overline{u}}+\delta)$ exists
and satisfies
$-h'({\overline{u}}+\delta)=f({\overline{u}}+\delta) \geq f({\overline{u}}) - \frac{\epsilon}{2n}$
(recall that $f$ is assumed continuous at ${\overline{u}}$).
Proposition~\ref{prop3} gives
\begin{equation}

\liminf_{n \rightarrow \infty} {\cal E}(X(\lfloor ({\overline{u}}+\delta) n \rfloor + i, n)
\geq f({\overline{u}}) - \frac{\epsilon}{2n}.
\end{equation}
Hence we have, uniformly for $u \leq {\overline{u}} + \delta$,
\begin{equation}

\limsup_{n \rightarrow \infty} \sum_{i \in F}
\bigl( \rho(\lfloor {\overline{u}} n \rfloor , \{i\}; n)
- \rho(\lfloor u n \rfloor , \{i\}; n) \bigr)
\leq \epsilon/2.
\end{equation}
This implies that \eqref{nolabel}
becomes eventually smaller than $\epsilon$,
uniformly in $u \leq {\overline{u}} + \delta$.

This completes the proof of \eqref{sixteen}.
The estimate \eqref{seventeen}
follows from \eqref{sixteen}
in combination with Proposition~\ref{prop4},
inequalities \eqref{thirteena} and \eqref{thirteenb},
and the fact that $\beta(s,\cdot)$
is essentially carried by a set of the form
$\{l: l \leq cm\}$ in the limit $m \rightarrow \infty$.

\label{prop7}
$h(u) \geq \frac{1-u}{2} - \frac12 \sqrt{\frac12 - u^2}$
for $|u| \leq \frac12$.

\label{prop8}
$h(u) \leq \frac{1-u}{2} - \frac12 \sqrt{\frac12 - u^2}$
for $|u| \leq \frac12$.

First assume $u>0$, and put $w=1/u$.
Assume that $u$ is irrational and that $h'(u)$ exists
(as must be the case for a dense set of $u$'s in $(0,\frac12)$).
We compute the expected value of $S(\lfloor un \rfloor,n)$, which is
the expected value of the number of particles
that have passed an observer traveling at speed $u$,
minus the number of particles that the observer has passed:
\begin{align*}
{\cal E} S(k, \lfloor kw \rfloor)
&= \tfrac12 \sum_{i=0}^{\lfloor kw \rfloor}
   P\bigl[
     X(\lfloor iu \rfloor, i) = 1,\;
     X(\lceil iu \rceil, i) = 0
   \bigr] \\
&\quad - \sum_{l=1}^k {\cal E} X(l, lw).
\end{align*}
Multiplying both sides by $u/k \approx 1/\lfloor kw \rfloor$ 
and taking the limit, one gets
\begin{align*}
h(u)
&= \lim_{k \rightarrow \infty} \frac{{\cal E} S(k,\lfloor kw \rfloor)}
{\lfloor kw \rfloor} \\
&= \frac12 \Big( \lim_{k \rightarrow \infty}
\frac{1}{\lfloor kw \rfloor} \sum_{i=0}^{\lfloor kw \rfloor} P [
X(\lfloor iu \rfloor , i) = 1, \ X(\lceil iu \rceil , i) = 0 ] \Big) \\
& \quad - \ \frac1w \Big( \lim_{k \rightarrow \infty}
\frac1k \sum_{l=1}^k {\cal E} X(l,lw) \Big) \\
&= \frac12 \lim_{N \rightarrow \infty} \frac1N \sum_{i=0}^{N-1}
\mu(\lfloor ui \rfloor,i) (x_0=1,\ x_1=0) \ -uf(u).
\end{align*}
The same argument shows that this formula holds
for negative $u$, too.
Thus this relation holds for a dense set of $u$'s
in $[-\frac12,\frac12]$.

Now, by Proposition~\ref{prop5}, any limit of
\begin{equation*}
\mu(\lfloor un \rfloor,n)(x_0=1,\ x_1=0)
\end{equation*}
as $n \rightarrow \infty$ is of the form
\begin{equation*}
\int (1-\sqrt{a^2+(1-a)^2}) \ \rho(da) \ \ \text{with} 
\ \ \int a \ \rho(da) = f(u)
\end{equation*}
(see the formula for the probability of the event $x_0=1$, $x_1=0$
calculated at the end of subsection~\ref{subsec:markov}).
Hence by Jensen's inequality we get
\begin{equation*}
\limsup_{n \rightarrow \infty} \mu(\lfloor un \rfloor,n)(x_0=1,\ x_1=0)
\leq 1-\sqrt{(f(u))^2+(1-f(u))^2}
\end{equation*}
so that
\begin{equation*}
{\scriptstyle \frac12} \lim_{N \rightarrow \infty} \sum_{i=0}^{N-1} 
\mu(\lfloor ui \rfloor,i)(x_0=1,\ x_1=0)
\leq {\scriptstyle \frac12}-{\scriptstyle \frac12} \sqrt{(f(u))^2+(1-f(u))^2}.
\end{equation*}
Hence
\begin{equation*}
h(u) \leq {\scriptstyle \frac12}-
{\scriptstyle \frac12} \sqrt{(f(u))^2+(1-f(u))^2} - uf(u).
\end{equation*}
Since $0 \leq f(u) \leq 1$, we have
\begin{equation*}
h(u) \leq \sup_{0 \leq b \leq 1} \Big\{ {\scriptstyle \frac12} - 
{\scriptstyle \frac12} \sqrt{b^2+(1-b)^2} - ub \Big\}.
\end{equation*}
This is maximized at $b = \frac12 - \frac{u}{\sqrt{2-4u^2}}$ (=$f(u)$).
Substituting, we get
$$h(u) \leq \frac12 - \frac12 \sqrt{\frac12 - u^2} - \frac{u}2.$$
